// Normaliza o retorno da Apify e calcula o score de engajamento.
//
// score bruto = curtidas + comentarios * 3
// score final = bruto dividido pela MEDIANA do próprio perfil.
//
// A normalização pela mediana é o que permite comparar um perfil de 50 mil
// seguidores com um de 3 mil: o que interessa é o post ter ido melhor que o
// normal daquele perfil, não o número absoluto.

const posts = items
  .map((i) => i.json)
  .filter((p) => p && (p.url || p.postUrl));

function tipoDoPost(p) {
  const t = String(p.type || p.productType || '').toLowerCase();
  if (t.includes('video') || t.includes('reel') || t.includes('clips')) return 'reel';
  if (t.includes('sidecar') || t.includes('carousel')) return 'carrossel';
  return 'imagem';
}

function mediana(numeros) {
  if (numeros.length === 0) return 0;
  const ordenados = [...numeros].sort((a, b) => a - b);
  const meio = Math.floor(ordenados.length / 2);
  return ordenados.length % 2
    ? ordenados[meio]
    : (ordenados[meio - 1] + ordenados[meio]) / 2;
}

const normalizados = posts.map((p) => {
  const curtidas = Number(p.likesCount ?? 0);
  const comentarios = Number(p.commentsCount ?? 0);
  return {
    perfil: '@' + String(p.ownerUsername || p.username || 'desconhecido'),
    url: String(p.url || p.postUrl),
    legenda: p.caption ? String(p.caption) : null,
    curtidas: curtidas < 0 ? 0 : curtidas,
    comentarios: comentarios < 0 ? 0 : comentarios,
    bruto: Math.max(0, curtidas) + Math.max(0, comentarios) * 3,
    publicado_em: p.timestamp ? new Date(p.timestamp).toISOString() : null,
    tipo: tipoDoPost(p),
  };
});

// Mediana por perfil.
const porPerfil = {};
for (const p of normalizados) {
  (porPerfil[p.perfil] = porPerfil[p.perfil] || []).push(p.bruto);
}
const medianas = {};
for (const perfil of Object.keys(porPerfil)) {
  medianas[perfil] = mediana(porPerfil[perfil]);
}

return normalizados.map((p) => {
  const base = medianas[p.perfil];
  // Perfil sem histórico útil (mediana zero) fica com o bruto, sem dividir
  // por zero e sem inventar um score alto.
  const score = base > 0 ? p.bruto / base : 0;
  return {
    json: {
      perfil: p.perfil,
      url: p.url,
      legenda: p.legenda,
      curtidas: p.curtidas,
      comentarios: p.comentarios,
      score_engajamento: Number(score.toFixed(4)),
      publicado_em: p.publicado_em,
      tipo: p.tipo,
    },
  };
});
